import { createServer, type ServerResponse } from "node:http";
import { spawn } from "node:child_process";
import { once } from "node:events";

type Reply = { status?: number; body?: string; json?: unknown; contentType?: string };
type BackendRoute = { request(): { url(): string }; fulfill(reply: Reply): Promise<void> };
export class Backend {
  handlers: { pattern: string; handle: (route: BackendRoute) => unknown }[] = [];
  waiters: { predicate: (request: {url(): string}) => boolean; resolve: () => void }[] = [];
  async route(pattern: string, handle: (route: BackendRoute) => unknown) { this.handlers.push({pattern, handle}); }
  waitForRequest(predicate: (request: {url(): string}) => boolean) { return new Promise<void>(resolve => this.waiters.push({predicate, resolve})); }
  async respond(url: string, response: ServerResponse) {
    const request = {url: () => url};
    for (const waiter of this.waiters) if (waiter.predicate(request)) waiter.resolve();
    const handler = this.handlers.findLast(({pattern}) => new RegExp("^" + pattern.split("*").map(part => part.replace(/[.+?^${}()|[\]\\]/g, "\\$&")).join(".*") + "$").test(url));
    if (!handler) { response.writeHead(404).end(); return; }
    await handler.handle({request: () => request, fulfill: async ({status = 200, body, json, contentType}) => {
      response.writeHead(status, {"content-type": contentType ?? (json === undefined ? "text/plain" : "application/json")});
      response.end(json === undefined ? body : JSON.stringify(json));
    }});
  }
